"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["66706"],{33510(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.alteracao_quebra_agregado_do_fato","status":422,"titulo":"A altera\xe7\xe3o deixaria de valer o agregado do fato"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.alteracao_quebra_agregado_do_fato","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova defini\xe7\xe3o de um fato do cat\xe1logo (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), mas h\xe1 um resumo de grupo que tem este fato como membro, e a defini\xe7\xe3o nova o deixaria inv\xe1lido. O resumo infere do fato de membro o tipo de dado, a quantidade de valores e a origem das op\xe7\xf5es, e n\xe3o pode proteger menos nem resolver antes dele. Mudar o tipo de dado ou a origem das op\xe7\xf5es do membro, tir\xe1-lo de fato declarado de membro de grupo, elevar a prote\xe7\xe3o de dados dele acima da do resumo ou adiar o ponto de resolu\xe7\xe3o dele para depois do do resumo desfaz essa coer\xeancia. A recusa s\xf3 conta o que a altera\xe7\xe3o causa: o resumo que j\xe1 estava inv\xe1lido antes n\xe3o trava. A corre\xe7\xe3o da defini\xe7\xe3o de um fato \xe9 regra do UNI-REQ-0159, e a API recusa a altera\xe7\xe3o que deixaria inv\xe1lido algo que j\xe1 cita o fato, em vez de alter\xe1-lo em sil\xeancio. Nada \xe9 gravado: o fato continua com a defini\xe7\xe3o anterior.","A recusa vem na lista `errors` da resposta, com `field` igual a `citacoes.agregados.<c\xf3digo do agregado>`, uma entrada por resumo de grupo afetado. A mensagem cita o motivo."],"comoResolver":["Escolha uma das sa\xeddas. Escolha uma defini\xe7\xe3o que mantenha o resumo v\xe1lido: mantenha o tipo de dado, a origem das op\xe7\xf5es e a condi\xe7\xe3o de fato declarado de membro de grupo, n\xe3o eleve a prote\xe7\xe3o de dados do membro acima da do resumo nem adie o ponto de resolu\xe7\xe3o do membro para depois do do resumo. Se \xe9 preciso elevar a prote\xe7\xe3o ou adiar o ponto de resolu\xe7\xe3o do membro, eleve antes a prote\xe7\xe3o ou adie antes o ponto de resolu\xe7\xe3o do resumo de grupo (os \xfanicos eixos que ele aceita alterar), para que ele continue protegendo pelo menos tanto quanto o membro e resolvendo depois dele. A mudan\xe7a de tipo de dado ou de origem das op\xe7\xf5es do membro n\xe3o tem como ser acompanhada pelo resumo: ela exige outro fato de membro. Desativar o resumo n\xe3o basta, porque ele continua sendo conferido.","A defini\xe7\xe3o corrigida vale para os rascunhos e para os processos novos; a vers\xe3o j\xe1 publicada de um processo n\xe3o muda."],"ondeAparece":["Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);